BEGIN;
CREATE TABLE identity.oauth_states(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE,provider text NOT NULL,state_hash text NOT NULL UNIQUE,redirect_uri text NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tracking.click_tokens(click_id uuid PRIMARY KEY REFERENCES tracking.clicks(id) ON DELETE CASCADE,tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE affiliate.conversion_distributions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE,conversion_id uuid NOT NULL UNIQUE REFERENCES tracking.conversions(id),gross numeric(20,8) NOT NULL CHECK(gross>=0),user_reward numeric(20,8) NOT NULL CHECK(user_reward>=0),referral_reward numeric(20,8) NOT NULL DEFAULT 0 CHECK(referral_reward>=0),costs numeric(20,8) NOT NULL DEFAULT 0 CHECK(costs>=0),platform_margin numeric(20,8) NOT NULL CHECK(platform_margin>=0),currency char(3) NOT NULL,ledger_transaction_id uuid REFERENCES ledger.transactions(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(abs(gross-(user_reward+referral_reward+costs+platform_margin))<0.00000001));
ALTER TABLE identity.oauth_states ENABLE ROW LEVEL SECURITY;ALTER TABLE identity.oauth_states FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_isolation ON identity.oauth_states USING(tenant_id=core.current_tenant_id()) WITH CHECK(tenant_id=core.current_tenant_id());
ALTER TABLE tracking.click_tokens ENABLE ROW LEVEL SECURITY;ALTER TABLE tracking.click_tokens FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_isolation ON tracking.click_tokens USING(tenant_id=core.current_tenant_id()) WITH CHECK(tenant_id=core.current_tenant_id());
ALTER TABLE affiliate.conversion_distributions ENABLE ROW LEVEL SECURITY;ALTER TABLE affiliate.conversion_distributions FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_isolation ON affiliate.conversion_distributions USING(tenant_id=core.current_tenant_id()) WITH CHECK(tenant_id=core.current_tenant_id());
CREATE INDEX idx_oauth_states_expiry ON identity.oauth_states(expires_at) WHERE used_at IS NULL;
CREATE INDEX idx_click_tokens_expiry ON tracking.click_tokens(expires_at);
COMMIT;